<script lang="ts">
	import * as Comments from "$lib/components/comments";
	import * as Reader from "$lib/components/reader";
	import NotFound from "$lib/components/ui/NotFound.svelte";

	const { data } = $props();
</script>

{#key data.chapter}
	{#if data.chapter}
		{#snippet reading(chapter: Chapter)}
			<Reader.Provider {chapter}>
				<Reader.Reader />
			</Reader.Provider>
		{/snippet}
		{#if data.chapter.relationships.thread}
			<Comments.Provider thread={data.chapter.relationships.thread}>{@render reading(data.chapter)}</Comments.Provider>
		{:else}
			{@render reading(data.chapter)}
		{/if}
	{:else}
		<NotFound />
	{/if}
{/key}
